# ── Cell 5: MERGE into new silver ─────────────────────────────────────────────
if DRY_RUN:
    print("DRY_RUN = True -> nothing written. Review the checks above, then set DRY_RUN = False.")
else:
    m = target.alias("t").merge(aligned.alias("s"), f"t.{MERGE_KEY} = s.{MERGE_KEY}")
    if OVERLAP_MODE == "fill_nulls":
        protect = {MERGE_KEY, "row_hash", "_silver_loaded_at"}
        m = m.whenMatchedUpdate(set={c: f"coalesce(t.`{c}`, s.`{c}`)"
                                     for c in tgt_cols if c not in protect})
    # "skip": matched rows untouched
    m.whenNotMatchedInsertAll().execute()

    mt = target.history(1).select("operationMetrics").collect()[0][0]
    print(f"✅ MERGE | inserted: {mt.get('numTargetRowsInserted')} | updated: {mt.get('numTargetRowsUpdated')}")

aligned.unpersist()
